    // Abstract operation:  Compares two elements in the array.
    // Precondition:  data[i] and data[j] are valid indices within the array.
    // Postcondition: Returns true if data[i] < data[j], false otherwise.
    public abstract boolean compare(int i, int j);

    // Abstract operation: Swaps two elements in the array.
    // Precondition:  data[i] and data[j] are valid indices within the array.
    // Postcondition:  data[i] and data[j] are swapped.
    public abstract void swap(int i, int j);
